  LanguageConfig_BonusCardAwardText_CN = {Text = "Gier-Bonus"},
  LanguageConfig_BonusCardRateText_CN = {
    Text = "“Der Mutterkern der Fülle“ erhält die starke Lust-Bonus: <NetworkDelayGreen:{s1}>"
  },
  LanguageConfig_BonusCardTipsContent_CN = {
    Text = "1. Schutzherren mit bestimmten Erweckern oder Schicksalsrädern (kein Aufstellen erforderlich) können einen zusätzlichen Fallbonus für den “Fertilitätssamenkern“ in den Belohnungen der “Verwirrte Begierde“-Quest erhalten (einschließlich Reproduktion). Die spezifischen Boni sind wie folgt: \n· Erwecker “Thais“: Erwachen 0/1/2/3 und mehr, Bonus 20%/30%/40%/50% \n· SSR Schicksalsrad “Barmherzige Pflege“: Stapelposition 0/1/2/3 und mehr, Bonus 20%/30%/40%/50% \n· SR Schicksalsrad “Glühender Abschiedskuss“: Stapelposition 0/1/2/3 und mehr, Bonus 20%/30%/40%/50% \n2. Die “Starke Begierde“-Boni verschiedener Erwecker oder Schicksalsräder werden kumulativ berechnet."
  },
  LanguageConfig_BonusCardTipsTitle_CN = {
    Text = "Gier-Bonus Erklärung"
  },
  LanguageConfig_BonusRuleContent_A24Activity_CN = {
    Text = "1. Schutzherr, der über einen bestimmten Erwecker oder Schicksrad verfügt (nicht erforderlich, um aufgestellt zu werden), kann die Belohnung der “Erinnerungscode“-Aufgaben im Level um zusätzliche Fallen von “Erinnerungspuzzle“ erhöhen (einschließlich Reproduktion), die spezifischen Boni sind wie folgt: \n·Erwecker “24“: Erwachen 0/1/2/3 und mehr, Bonus 20%/30%/40%/50%\n·SSR Schicksrad “Verstümmelungsrückprall“: Stapelposition 0/1/2/3 und mehr, Bonus 20%/30%/40%/50%\n·SR Schicksrad “Entschlossenheit des Silberkabeljaus“: Stapelposition 0/1/2/3 und mehr, Bonus 20%/30%/40%/50%\n2. Die “Rationalitätsboni“ verschiedener Erwecker oder Schicksräder werden kumulativ berechnet."
  },
  LanguageConfig_BonusRuleContent_ArachneActivity_CN = {
    Text = "1,Der Schutzherr besitzt einen bestimmten Erwecker oder ein Schicksalsrad (nicht erforderlich im Einsatz), um in den Belohnungen der „Bühne der Puppe\"-Levelaufgabe einen zusätzlichen Droppbonus für das „Samt-Sitzplatzticket\" zu erhalten, die spezifischen Boni sind wie folgt: \n· Erwecker „Arachne\": Erwachen 0/1/2/3 und mehr, Bonus 20%/30%/40%/50%. \n· SSR Schicksalsrad „Netz der Ewigen Weberkunst\": Stapelposition 0/1/2/3 und mehr, Bonus 20%/30%/40%/50%. \n· SR Schicksalsrad „Glücksrad\": Stapelposition 0/1/2/3 und mehr, Bonus 20%/30%/40%/50%. \n2,Die „Aktivitätsboni\" verschiedener Erwecker oder Schicksalsräder werden kumulativ berechnet."
  },
  LanguageConfig_BonusRuleContent_CarabooActivity_CN = {
    Text = "1. Schutzherren, die bestimmte Erwecker oder Schicksräder besitzen (müssen nicht eingesetzt sein), können zusätzliche Dropboni für „Roter Apfel“, „Goldener Apfel“ und „Kandierter Apfel“ in den Stufenmissionsbelohnungen von „Umapatis Schätze“ erhalten. Die spezifischen Boni sind wie folgt:\nErwecker „Caraboo“: Erwachen 0/1/2/3 oder höher, Bonus 20%/30%/40%/50%.\nSSR-Schicksrad „Honigfrucht der Lüge“: Stapelposition 0/1/2/3 oder höher, Bonus 20%/30%/40%/50%.\nSR-Schicksrad „Schöne Wahrheit“: Stapelposition 0/1/2/3 oder höher, Bonus 20%/30%/40%/50%.\n2. „Eventboni“ von verschiedenen Erweckern oder Schicksrädern werden kumulativ berechnet."
  },
  LanguageConfig_BonusRuleContent_CastorActivity_CN = {
    Text = "1. Schutzherren mit bestimmten Erweckern oder Schicksrädern (keine Aufstellung erforderlich) können die Belohnungen der “Flug über den Himmel“ Quest für die “Common Sense Buch“, “Mathematikbuch“ und “Literaturbuch“ um zusätzliche Drop-Boni erhöhen, die spezifischen Boni sind wie folgt: \n· Erwecker “Castor“: Erwachen 0/1/2/3 und höher, Bonus 20%/30%/40%/50%. \n· SSR Schicksrad “Unerträgliche Freiheit“: Stapelposition 0/1/2/3 und höher, Bonus 20%/30%/40%/50%. \n· SR Schicksrad “Einsame Feder“: Stapelposition 0/1/2/3 und höher, Bonus 20%/30%/40%/50%. \n2. Verschiedene Erwecker oder Schicksräder “Aktivitätsboni“ werden kumulativ berechnet."
  },
  LanguageConfig_BonusRuleContent_ClementineActivity_CN = {
    Text = "1. Schutzherr hat bestimmte Erwecker oder Schicksalsrad (keine Aufstellung erforderlich), die es ermöglichen, dass der “Diagnosebericht“ in den Belohnungen der Mission “Furchtheilung“ einen zusätzlichen Fallbonus erhält (einschließlich Reproduktion), die spezifischen Boni sind wie folgt: \n· Erwecker “Clementine“: Erwachen 0/1/2/3 und höher, Bonus 20%/30%/40%/50% \n· SSR Schicksalsrad “Verschleierte Qual“: Stapelposition 0/1/2/3 und höher, Bonus 20%/30%/40%/50% \n· SR Schicksalsrad “Hypnotisches Pendel“: Stapelposition 0/1/2/3 und höher, Bonus 20%/30%/40%/50% \n2. Die “Aktivitätsboni“ verschiedener Erwecker oder Schicksalsräder werden additiv berechnet."
  },
  LanguageConfig_BonusRuleContent_DaffodilActivity_CN = {
    Text = "1. Hüter, die über bestimmte Erwecker oder Schicksalsräder (keine Aufstellung erforderlich) verfügen, können in der “Hexenladen“-Mission zusätzliche Belohnungen für die Gegenstände “Schädel des blassen Tieres“, “Schattenbestien-Schädel“ und “Scharlachrotes Biestschädel“ erhalten (einschließlich Reproduktion), die spezifischen Boni sind wie folgt: \n· Erwecker “Daffodil“: Erwachen 0/1/2/3 und mehr, Bonus 20%/30%/40%/50% \n· SSR Schicksalsrad “Kostbare Sammlung“: Stapelposition 0/1/2/3 und mehr, Bonus 20%/30%/40%/50% \n· SR Schicksalsrad “Hexenbreitkrempenhut“: Stapelposition 0/1/2/3 und mehr, Bonus 20%/30%/40%/50% \n2. Die “Aktivitätsboni“ verschiedener Erwecker oder Schicksalsräder werden auf additive Weise berechnet."
  },
  LanguageConfig_BonusRuleContent_DoresainActivity_CN = {
    Text = "1. Schutzherren, die über einen bestimmten Erwecker oder ein Schicksalsrad verfügen (nicht erforderlich im Einsatz), können die “Seelenfestmahl“-Mission Belohnung “verrottete Handknochen“ mit einem zusätzlichen Drop-Bonus versehen. Die spezifischen Boni sind wie folgt: \n· Erwecker “Doresain“: Erwachen 0/1/2/3 und mehr, Bonus 20%/30%/40%/50%. \n· SSR Schicksalsrad “Kuss der Ruhe“: Stapelposition 0/1/2/3 und mehr, Bonus 20%/30%/40%/50%. \n· SR Schicksalsrad “Makabre Delikatessen“: Stapelposition 0/1/2/3 und mehr, Bonus 20%/30%/40%/50%. \n2. Die “Aktivitätsboni“ verschiedener Erwecker oder Schicksalsräder werden kumulativ berechnet."
  },
  LanguageConfig_BonusRuleContent_GenesisTinctActivity_CN = {
    Text = "1. Schutzherren, die bestimmte Erwecker oder Schicksräder besitzen (Einsatz nicht erforderlich), erhalten zusätzliche Dropboni für „Vorgeschlagene Übersetzung“ in den Stufenmissionsbelohnungen von „Vorgeschlagene Übersetzung“ (einschließlich Reproduktion). Die spezifischen Boni sind wie folgt:\nErwecker „Lotan: Cetarchon“: Erwachen 0/1/2/3 oder höher, Bonus 20%/30%/40%/50%.\nSSR-Schicksrad „Vorgeschlagene Übersetzung“: Stapelposition 0/1/2/3 oder höher, Bonus 20%/30%/40%/50%.\nSR-Schicksrad „Vorgeschlagene Übersetzung“: Stapelposition 0/1/2/3 oder höher, Bonus 20%/30%/40%/50%.\n2. „Eventboni“ von verschiedenen Erweckern oder Schicksrädern werden kumulativ berechnet."
