  LanguageConfig_DiamondDonateDesc_CN = {
    Text = "Jeder Tropfen Silberprimus, den Sie spenden, ist von unschätzbarem Wert; sie werden in die Auflösungsforschung und den Bau von Schulgebäuden investiert, um Teil von Mythag zu werden, um gemeinsam in diese unvergessliche Zukunft zu streben.\n Möge der Silberschlüssel uns führen"
