  LanguageConfig_LotteryPhoneticDialogue10_CN = {
    Text = "Sei noch frommer, opfere noch mehr... Gottes Reich beobachtet deine Gebete, eines Tages wird es antworten"
  },
  LanguageConfig_LotteryPhoneticDialogue11_CN = {
    Text = "Selbst die gewöhnlichsten Menschen können von diesen Versen berührt werden... Diese Blume blüht für dich!"
  },
  LanguageConfig_LotteryPhoneticDialogue12_CN = {
    Text = "Gedichte haben ihre eigenen Emotionen, wie Blumen ihre Sprache. Dies ist für dich"
  },
  LanguageConfig_LotteryPhoneticDialogue13_CN = {
    Text = "Bitte schau hin, ich werde für immer kämpfen"
  },
  LanguageConfig_LotteryPhoneticDialogue14_CN = {
    Text = "Bist du hier, um meinen Triumph zu bezeugen?"
  },
  LanguageConfig_LotteryPhoneticDialogue15_CN = {
    Text = "Kämpf weiter, kämpf weiter, braves Kind, möchtest du, dass der Lehrer dir den Kopf tätschelt?"
  },
  LanguageConfig_LotteryPhoneticDialogue16_CN = {
    Text = "Mit diesem Schrott wirst du nichts retten können?"
  },
  LanguageConfig_LotteryPhoneticDialogue17_CN = {
    Text = "Ach, der Gast hat wirklich Glück gehabt. Möchtest du es noch einmal versuchen?"
  },
  LanguageConfig_LotteryPhoneticDialogue18_CN = {
    Text = "Möchtest du noch etwas anderes ansehen? In meinem Laden habe ich noch wertvollere Waren."
  },
  LanguageConfig_LotteryPhoneticDialogue19_CN = {
    Text = "Dieser Bericht ist sehr lecker, danke für die Gastfreundschaft."
  },
  LanguageConfig_LotteryPhoneticDialogue1_CN = {
    Text = "Danke für deine Liebe, Liebling"
  },
  LanguageConfig_LotteryPhoneticDialogue20_CN = {
    Text = "Hmm, ich habe es angenommen. Gibt es noch etwas anderes?"
  },
  LanguageConfig_LotteryPhoneticDialogue21_CN = {
    Text = "Danke für dein Geschenk. Bitte nimm dies an."
  },
  LanguageConfig_LotteryPhoneticDialogue22_CN = {
    Text = "Ich habe einige wertvolle Materialien gefunden. Ich hoffe, sie können dir helfen."
  },
  LanguageConfig_LotteryPhoneticDialogue23_CN = {
    Text = "Ein einfaches Vorspiel, guten Appetit beim Mahl."
  },
  LanguageConfig_LotteryPhoneticDialogue24_CN = {
    Text = "Schmeckt Ihnen das Hauptgericht, das vom Heiligen Herrn persönlich zubereitet wurde, edler Gast?"
  },
  LanguageConfig_LotteryPhoneticDialogue25_CN = {
    Text = "Achte nicht zu sehr auf Techniken und Regeln."
  },
  LanguageConfig_LotteryPhoneticDialogue26_CN = {
    Text = "Vernunft lehrt dich nur zu skizzieren, Wahnsinn hingegen lässt dich erschaffen."
  },
  LanguageConfig_LotteryPhoneticDialogue27_CN = {
    Text = "Die Menschen fürchten den Wahnsinn, weil sie die Wahrheit nie gesehen haben."
  },
  LanguageConfig_LotteryPhoneticDialogue28_CN = {
    Text = "Hast du es gesehen? Die wahre Welt!"
  },
  LanguageConfig_LotteryPhoneticDialogue29_CN = {
    Text = "Ich habe die echten Farben gesehen, wie wunderbar."
  },
  LanguageConfig_LotteryPhoneticDialogue2_CN = {
    Text = "Ach, das ist wirklich Glück! Halte es gut fest"
  },
  LanguageConfig_LotteryPhoneticDialogue30_CN = {
    Text = "Verrücktheit und Absurdität sind die wahre Schönheit der Realität, die Schönheit der Kunst!"
  },
  LanguageConfig_LotteryPhoneticDialogue31_CN = {
    Text = "Schwarz, Schwarz ist immer noch hier, reinige weiter deine Sünden."
  },
  LanguageConfig_LotteryPhoneticDialogue32_CN = {
    Text = "Wie schön, ich habe deine reine Seele gesehen..."
  },
  LanguageConfig_LotteryPhoneticDialogue33_CN = {
    Text = "Hey, Hüter! Selbst wenn sich die Dinge damals wiederholen würden, würdest du mich retten, oder? \n... Dann könnte ich beruhigt schlafen. Danke, äh, ich meine, danke."
  },
  LanguageConfig_LotteryPhoneticDialogue34_CN = {
    Text = "In letzter Zeit träume ich ständig von früheren Dingen, zum Verzweifeln, dieses Zeug sollte wenigstens nützlich sein."
  },
  LanguageConfig_LotteryPhoneticDialogue35_CN = {
    Text = "Die Göttliche Mutter hat ein erhabenes Opfer für das Göttliche Reich gebracht, wir sind bereit, alles für ihren Frieden zu geben."
  },
  LanguageConfig_LotteryPhoneticDialogue36_CN = {
    Text = "Vielen Dank für das Angebot an die Göttliche Mutter, ich hoffe, das wird ihr eine gute Nacht bescheren."
  },
  LanguageConfig_LotteryPhoneticDialogue37_CN = {
    Text = [[
Dieser Traum wird endlos weitergehen, und du... 
 Sei froh, ich werde dir erlauben, Teil davon zu sein.]]
  },
  LanguageConfig_LotteryPhoneticDialogue38_CN = {
    Text = "Hast du schon einmal gesehen, wie mein Traum aussieht? Diese unreinen und bis ins Extrem schmutzigen Szenen..."
  },
  LanguageConfig_LotteryPhoneticDialogue39_CN = {
    Text = "Weltliche Besitztümer sind so überflüssig. Wenn du irgendwelche Wünsche hast, sprich einfach direkt mit mir..."
  },
  LanguageConfig_LotteryPhoneticDialogue3_CN = {
    Text = "Du hast wirklich einen Schatz gefunden, junger Mann. Alles in meinem Laden sind antike Relikte!"
  },
  LanguageConfig_LotteryPhoneticDialogue40_CN = {
    Text = "Wenn du dich in den antiken Ruinen des Fernen Ostens befindest, erinnere dich daran, niemals leichtfertig Opfer darzubringen – Dämonen und wilde Füchse? Ha... sie sind kaum der Erwähnung wert."
  },
  LanguageConfig_LotteryPhoneticDialogue41_CN = {
    Text = "Kohleball, der Beste!"
  },
  LanguageConfig_LotteryPhoneticDialogue42_CN = {
    Text = "Kohleball, beeindruckend!"
  },
  LanguageConfig_LotteryPhoneticDialogue43_CN = {
    Text = "Glänzend! Geschenkt für, Kohleball!"
  },
  LanguageConfig_LotteryPhoneticDialogue44_CN = {
    Text = "Freund, ich mag es! Mosk, Kohleball, tauscht aus!"
  },
  LanguageConfig_LotteryPhoneticDialogue45_CN = {
    Text = "Muscheln, so schön! Mosk, sammeln! Kohleball, Belohnung!"
  },
  LanguageConfig_LotteryPhoneticDialogue46_CN = {
    Text = "Mosk, gefällt mir! Danke, Kohleball!"
  },
  LanguageConfig_LotteryPhoneticDialogue47_CN = {
    Text = "Ganz recht... Du, der vom Schicksal verstoßen wurde, zerschmettere nun seinen Käfig!"
  },
  LanguageConfig_LotteryPhoneticDialogue48_CN = {
    Text = "Ah, ein grausamer kleiner Scherz des Schicksals."
  },
  LanguageConfig_LotteryPhoneticDialogue49_CN = {
    Text = "Fortpflanzung, Wachstum – all das hängt eng mit Liebe zusammen."
  },
  LanguageConfig_LotteryPhoneticDialogue4_CN = {
    Text = "Von so mächtiger Magie ausgewählt zu werden, bist du das auserwählte Kind der Legende?"
  },
  LanguageConfig_LotteryPhoneticDialogue50_CN = {
    Text = "Als ich allein in jener Welt ankam, hat mir jemand sehr, sehr viel beigebracht, und bis heute bemühe ich mich stets weiterzulernen."
  },
  LanguageConfig_LotteryPhoneticDialogue51_CN = {
    Text = [[
Wurdest du jemals von jemandem vorbehaltlos geliebt, oder hast du selbst jemanden geliebt, dem du alles gegeben hast?
Ich finde, das ist etwas sehr Wunderbares.]]
  },
  LanguageConfig_LotteryPhoneticDialogue52_CN = {
    Text = "Die Liebe der Menschen – nein, die Liebe aller Lebewesen – ist wirklich wundersam.\nEin Wesen, das wichtiger ist als man selbst, wichtiger als alles andere."
  },
  LanguageConfig_LotteryPhoneticDialogue53_CN = {
    Text = "Bitte warte gemeinsam mit mir auf den Beginn jener strahlenden, glänzenden, wunderschönen Welt."
  },
  LanguageConfig_LotteryPhoneticDialogue54_CN = {
    Text = "Danke für dein Geschenk – es wird wohl zu einigen neuen Entdecken führen."
  },
  LanguageConfig_LotteryPhoneticDialogue55_CN = {
    Text = "Was? Im Ernst? Du hast gerade den Jackpot geknackt?!"
  },
  LanguageConfig_LotteryPhoneticDialogue56_CN = {
    Text = "Du glaubst wirklich jedem Wort eines kleinen Mädchens?"
  },
  LanguageConfig_LotteryPhoneticDialogue57_CN = {
    Text = "Wunderbar! Nein, was ich suche, ist nicht dabei ... aber ich freue mich so sehr für alle anderen, die gewonnen haben."
  },
  LanguageConfig_LotteryPhoneticDialogue58_CN = {
    Text = "Ich ... ich bin sicher, dass all eure Wünsche in Erfüllung gehen werden. Daran glaube ich fest."
  },
  LanguageConfig_LotteryPhoneticDialogue59_CN = {
    Text = "Hehe, komm schon, lauf nicht weg~ Genieß es richtig, das ist das Echte – der Segen der Fee persönlich!"
  },
  LanguageConfig_LotteryPhoneticDialogue5_CN = {
    Text = "Hmm? Ah, nimm es. Danke für deine Freundlichkeit oder so"
  },
  LanguageConfig_LotteryPhoneticDialogue60_CN = {
    Text = "So knapp, nur noch ein winziges bisschen mehr! Noch ein Versuch, hmm?"
