  LanguageConfig_PVPMatchVictory_CN = {Text = "Sieg"},
  LanguageConfig_PVPOpeningVoiceUnlockDesc_CN = {
    Text = "Wird freigeschaltet, nachdem dieser Dialog im Phasenduell ausgelöst wurde"
  },
  LanguageConfig_PVPRankRewardCountdown_CN = {
    Text = "Saison verbleibend {s1} Tage {s2} Stunden"
  },
  LanguageConfig_PVPRankingRuleDesc_CN = {
    Text = "<Title:[Leaderboard]>\n[Vorgruppe] und [Wahlmodus] haben jeweils eigene unabhängige Saisons und Saisonranglisten. Saisonranglistenbelohnungen werden am Ende jeder Saison abgerechnet.\nDie Teilnahme an einem Match während der aktuellen Saison platziert Sie in der Saisonrangliste für den entsprechenden Modus. Ein Sieg während der aktuellen Saison berechtigt zum Erhalt von Belohnungen basierend auf Ihrer aktuellen Saisonplatzierung am Ende der Saison.\n<Title:[Rangverhältnis]>\nDie Titel im Duell basieren auf den Teilnahmepunkten, die Verteilung ist wie folgt:\n     Apex: die oberen 2%\n     Phasendominator: 2%~10%\n     Schachmeister: 10%~25%\n     Phasenelite: 25%~50%\n     Schachlehrling: 50%~75%\n     Phasenneuling: nach 75%\nWenn andere Schutzherren die gleiche Punktzahl haben, erfolgt die Sortierung nach dem Eintritt in die Rangliste, jedoch bleiben die Titel und Belohnungen gemäß der höchsten Platzierung dieser Punkte bestehen."
  },
