  LanguageConfig_PermanentActivityRuleContent_CN = {
    Text = "<Title:Arcade>\nAktivitäten mit dem Tag „Arcade\" werden nach Ablauf der Aktivitätszeit in „Arcade\" aufgenommen, sodass die entsprechenden Spielmechaniken und die Handlung weiterhin in „Arcade\" erlebt werden können.\n\n<Title:Aufnahmeregeln>\nAktivitäten mit dem Tag „Arcade\" bieten reichhaltige zeitlich begrenzte Belohnungen. Nach Ablauf der Aktivitätszeit können die zeitlich begrenzten Belohnungen nicht mehr abgeholt werden, bitte die Schutzherren, die zeitlich begrenzten Belohnungen rechtzeitig abzuholen.\nNach der Aufnahme der Aktivität in „Arcade\" wird der vorherige Fortschritt automatisch beibehalten, sodass die Schutzherren weiterhin erleben können."
  },
