  LanguageConfig_RPGJJC_Desc_CN = {
    Text = "Du kannst “Übungsabzeichen“ verbrauchen, um die VERTsteams anderer Schutzherren herauszufordern. Bei erfolgreichem Herausforderungsabschluss wirst du in der Rangliste aufsteigen. Du musst auch dein VERTsteam sorgfältig aufstellen, sonst könnte es von anderen Schutzherren erfolgreich herausgefordert werden und deine Rangliste könnte fallen. Je höher dein Rang, desto mehr “Übungsabzeichen“ erhältst du pro Stunde. “Übungsabzeichen“ werden automatisch über die Zeit gewonnen. “Übungsabzeichen“ können im Austauschgeschäft gegen Rosenskripte, Geisterwissenextrakte und andere Gegenstände eingelöst werden."
  },
