  LanguageConfig_RailWayLevelAdjustmentTipsContent_CN = {
    Text = "Im “Rasender Freude-Express“ gibt es ein Kompensationsmechanismus für Level, die spezifischen Regeln sind wie folgt: \n  · Im Ermittlungsteam werden Erwecker, deren Level unter 60 liegt, in dieser Herausforderung auf Level 60 kompensiert. \n  · Im Ermittlungsteam werden Erwecker, deren Fähigkeitslevel unter 5 liegt, in dieser Herausforderung auf Level 5 kompensiert. \n  · Im Ermittlungsteam werden Erwecker, deren “Wahnsinnsomen“ unter 6 liegt, in dieser Herausforderung auf Level 6 kompensiert. \n  · Im Ermittlungsteam werden Erwecker, deren “Seelenschmiede-Begabung“ unter 5 liegt, in dieser Herausforderung auf Level 5 kompensiert. \n  · Wenn der Schutzherr unter Level 60 liegt, wird er in dieser Herausforderung auf Level 60 kompensiert."
  },
