  LanguageConfig_RailWayStageCrazyMileExpGetDescV2_CN = {
    Text = "In diesem Ermittlungseinsatz können maximal {s1} „VIP-Punkte“ erhalten werden.\nEs wurden {s3} Mal „Notfall-Gnosis-Körper“ eingesetzt, aktuell wurden {s2} „VIP-Punkte“ erhalten.\n  ·Erste Phase: Elite/Anführer besiegen erhält „VIP-Punkte“ ×25/75\n  ·Zweite Phase: Elite/Anführer besiegen erhält „VIP-Punkte“ ×50/150\n  ·Dritte Phase: Elite/Anführer besiegen erhält „VIP-Punkte“ ×75/225 \n  ·Im Schwierig/Wahnsinnsmodus erhaltene „VIP-Punkte“ werden um 150%/400% erhöht.\n  ·Das Besiegen des Anführers der vierten Phase im Wahnsinnsmodus bringt zusätzlich „VIP-Punkte“ × 1500.\n  ·Pro eingesetztem „Notfall-Gnosis-Körper“ werden die „VIP-Punkte“ um 20% reduziert."
  },
  LanguageConfig_RailWayStageCrazyMileExpGetDesc_CN = {
    Text = "In dieser Ermittlung können maximal {s1} VIP-Punkte verdient werden. \nNotfall-Gnosis-Körper verwendet: {s3}. Derzeit verdient: {s2} VIP-Punkte.\nErste Phase: Besiege Elite/Anführer und erhalte 25/75 VIP-Punkte.\nZweite Phase: Besiege Elite/Anführer und erhalte 50/150 VIP-Punkte.\nDritte Phase: Besiege Elite/Anführer und erhalte 75/225 VIP-Punkte.\nSchwierig/Wahnsinn-Schwierigkeitsgrad erhöht die verdienten VIP-Punkte um 150%/400%.\nJede Verwendung eines Notfall-Gnosis-Körpers reduziert die VIP-Punkte um 20%."
  },
  LanguageConfig_RailWayStageCrazyNowDescV2_CN = {
    Text = "Der Wahnsinnsmodus hat 4 Phasen. In den ersten 3 Phasen gibt es jeweils 6 Kämpfe. In Phase 4 wird direkt der finale Anführer herausgefordert.\nDerzeit befindet man sich in Phase {s1} - Kampf {s2}."
  },
  LanguageConfig_RailWayStageCrazyNowDesc_CN = {
    Text = "In der aktuellen Untersuchung gibt es 3 Phasen, in jeder Phase 6 Kämpfe. \n Du befindest dich derzeit in Phase {s1} - Kampf {s2}."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent1_CN = {
    Text = "<Title:Phasen-Belohnungen>\nErste Phase: Besiege Elite/Anführer und erhalte „VIP-Punkte„ ×25/75 \nZweite Phase: Besiege Elite/Anführer und erhalte „VIP-Punkte„ ×50/150 \nDritte Phase: Besiege Elite/Anführer und erhalte „VIP-Punkte„ ×75/225\n<Title:Start-Relikte>\nZu Beginn erhältst du „Klein Ns Makellose Kamera„.\n<OrangeQuality:Goldene Harmonie>: „Arithmetica-Harmonie„ erhöht die Arithmetica-Kosten nur noch um 1. Jede 1% Schadenamplifikation erhöht die Tiefe der Erkenntnisforschung um 1%.\n<RedQuality:Fernreise Müdigkeit>: Heilungseffekte im Kampf –50%."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent2_CN = {
    Text = "<Title:Besondere Regeln>\nJe höher die Schwierigkeit, desto mehr VIP-Punkte erhältst du. Nach Abschluss aller drei Phasen erhöhen sich die VIP-Punkte um 150%.\n<Title:Start-Relikte>\nZu Beginn erhältst du „Klein Ns Abgenutzte Kamera„.\n<OrangeQuality:Goldene Harmonie>: „Arithmetica-Harmonie„ erhöht die Arithmetica-Kosten nur noch um 1. Jede 1% Schadenamplifikation erhöht die Tiefe der Erkenntnisforschung um 1%.\n<OrangeQuality:Dimensionsgeschenk>: Zu Beginn erhältst du zufällig 1 Relikt aus der Dimension. Hand-Limit +1.\n<RedQuality:Fernreise Müdigkeit>: Heilung im Kampf –50%.\n<RedQuality:Betäubungszeichen>: Zu Beginn des Kampfes wird das aktuelle Aliemus/Keyflare um –50% verringert."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3V2_CN = {
    Text = "<Title:Besondere Herausforderung>\nIm Wahnsinnsmodus wird nach Abschluss der dritten Phase zusätzlich der finale Anführer der vierten Phase „Tawil„ herausgefordert.\n<Title:Level-Belohnungen>\nJe höher die Herausforderungsschwierigkeit, desto mehr „VIP-Punkte„ werden erhalten. Die durch Abschluss der drei Phasen erhaltenen „VIP-Punkte„ werden um 400% erhöht.\nNach dem Besiegen des finalen Anführers „Tawil„ können zusätzlich „VIP-Punkte„ × 1500 erhalten werden.\n<Title:Anfängliche Relikte>\nZu Beginn der Ermittlung wird das Relikt „Klein Ns Chaotische Kamera„ erhalten.\n·<OrangeQuality:Goldene Harmonie>: Der durch „Arithmetica-Harmonie„ erzielte Arithmetica-Erhöhungseffekt beträgt maximal 1 Punkt. Für jeden 1% Schadenamplifikation wird der Effekt der Tiefe der Erkenntnisforschung um 1% erhöht.\n·<OrangeQuality:Dimensionsgeschenk>: Zu Beginn der Erkundung wird zufällig 1 Dimensionsbild-Relikt erhalten und die maximale Handgröße um 2 erhöht.\n·<OrangeQuality:Gesegnetes Ritual>: Die Anführerbelohnungen der ersten und zweiten Phase werden in 3 zufällige gesegnete Relikte zur Auswahl geändert.\n·<RedQuality:Fernreise Müdigkeit>: Alle LP-Heilungseffekte im Kampf werden um 50% reduziert.\n·<RedQuality:Betäubungszeichen>: Zu Beginn des Kampfes werden der aktuelle Aliemus und Keyflare aller Erwecker um 50% gesenkt.\n·<RedQuality:Ewiger Nachtkorridor>: Zu Beginn der Erkundung werden der Basis-Aliemus und das Keyflare-Maximum aller Erwecker um 50% erhöht."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3_CN = {
    Text = "<Title:Besondere Regeln>\nJe höher die Schwierigkeit, desto mehr VIP-Punkte erhältst du. Nach Abschluss aller drei Phasen VIP-Punkte +400%.\n<Title:Start-Relikte>\nZu Beginn erhältst du das Relikt „Klein Ns Chaotische Kamera„.\n<OrangeQuality:Goldene Harmonie>: „Arithmetica-Harmonie„ erhöht die Arithmetica-Kosten nur noch um 1. Jede 1% Schadenamplifikation erhöht die Tiefe der Erkenntnisforschung um 1%.\n<OrangeQuality:Dimensionsgeschenk>: Zu Beginn erhältst du zufällig 1 Dimensions-Relikt. Handlimit +2.\n<OrangeQuality:Gesegnetes Ritual>: Phase 1 und Phase 2 Bosse lassen ein gesegnetes Relikt (3 zur Auswahl) fallen.\n<RedQuality:Fernreise Müdigkeit>: Heilung –50%.\n<RedQuality:Betäubungszeichen>: Zu Beginn des Kampfes wird das aktuelle Aliemus und Keyflare aller Erwecker um 50% verringert.\n<RedQuality:Ewiger Nachtkorridor>: Basis-Aliemus und Keyflare-Obergrenze +50%."
  },
