  LanguageConfig_ResonanceRewardTagText_CN = {
    Text = "Resonanz-Bonus"
  },
  LanguageConfig_ResonanceRules_CN = {
    Text = "1. Jedes Kapitel der Ermittlung hat Resonanz, die während der Untersuchung starke Unterstützung bieten kann. \n2. Bei der Erstdurchquerung eines Levels erhält man Materialien zur Verbesserung der Resonanz, die verbraucht werden können, um die Resonanzeffekte zu aktivieren. \n3. Resonanz wird an Knotenpunkten auf der Karte erscheinen. Das Bewegen zu einem Resonanzknoten während dieser Erkundung aktiviert die Resonanz."
  },
  LanguageConfig_ResonanceSelectCard_CN = {
    Text = "Wähle 1 Karte zur Kopie"
  },
  LanguageConfig_ResonanceText_CN = {Text = "Resonanz"},
  LanguageConfig_ResonanceTipsName_CN = {Text = "“%s“"},
  LanguageConfig_ResonanceUnlockText_CN = {
    Text = "Nicht freigeschaltet"
  },
  LanguageConfig_ResonanceUnlockTips_CN = {
    Text = "Nach Aktivierung{s1} freigeschaltet"
  },
  LanguageConfig_ResonanceUnlock_And_CN = {Text = "Und"},
  LanguageConfig_ResonanceUnlock_Or_CN = {Text = "Oder"},
  LanguageConfig_ResonanceUpgradeText_CN = {Text = "Aufstieg"},
  LanguageConfig_Resonance_Group_Desc_1_CN = {
    Text = "Am Knotenpunkt[Eine gut gemeinte Gabe] kannst du 1 „naives Geschenk“ zu deinem Deck hinzufügen - Kosten-Plan von 1, gewähre dem niedrigsten Awakener 30 Wahnsinn, Kosten"
  },
  LanguageConfig_Resonance_Group_Desc_24_CN = {
    Text = "Bestimme einen Erwecker im Ereignis “Weg des Wahnsinns“, um seine Geisterspaltung zu verursachen und die anfänglichen vier Befehlskarten zu verlieren. Danach wird der Weg erscheinen und du erhältst 3 aus 1 Goldene Kreation. \n Du kannst in den folgenden vier Ereignissen “Geistfragment“ die verlorenen Befehlskarten nacheinander zurückgewinnen. Die zurückgewonnenen Befehlskarten erhalten direkt das einzigartige <EnsembleKeywords:“Ensemble“> Gebet."
  },
  LanguageConfig_Resonance_Group_Desc_2_CN = {
    Text = "Am Knotenpunkt[Unvollendete Wachsskulptur] kannst du 1 Karte wählen und ihre kosten um 1 reduzieren"
  },
  LanguageConfig_Resonance_Group_Desc_3_CN = {
    Text = "Am Knotenpunkt[Seltsame Geschwüre] kannst du eine „Herz der Verzerrung“ Karte zu deinem Deck hinzufügen, Kosten-Plan von 0, nachdem du sie spielst, lege alle deine Handkarten ab und ziehe plus 1 der abgelegten Karten, Kosten"
  },
  LanguageConfig_Resonance_Group_Desc_4_CN = {
    Text = "Am Knotenpunkt[Honigsüßer Wein] kannst du eine „Honigsüße Wein“-Karte zu deinem Deck hinzufügen - Kosten-Plan von 1, erhalte 1 temporäre Barriere, Kosten"
  },
  LanguageConfig_Resonance_Group_Desc_5_CN = {
    Text = "An den Knotenpunkt [Proxyritual] in der Stufe “Versessene“ und in den folgenden Stufen kann der Effekt “Göttliches Armglied“ erhalten werden – am Ende der Runde verursache Schaden in Höhe von 10% des maximalen Lebens deiner eigenen Gruppe an den Gegnern in der Frontreihe. \n Eine Karte “Das Urteil des Vollstreckers“ kann dem Kartendeck hinzugefügt werden – 0 Arithmetica-Kosten, nach dem Spielen verliere 10% der aktuellen Gesundheit, wodurch “Göttliches Armglied“ 3 Mal Schaden an den Gegnern in der Hinterreihe verursacht, im Bosskampf sogar 10 Mal. Verbrauch."
  },
  LanguageConfig_Resonance_Group_Desc_6_CN = {
    Text = "Am “reinen Segel“ füge eine “Utopischer Schleier“-Karte zu deinem Deck hinzu. 1 Arithmetica-Kosten, überprüfe 3 Schlüssel, die sich von den aktuell getragenen unterscheiden, wähle 1 aus, um sie sofort freizugeben, ohne die Abklingzeit des Schlüssels auszulösen. In Anführer Kämpfen kann es 1 Mal zusätzlich verwendet werden. Verbrauch."
  },
  LanguageConfig_Resonance_Group_Desc_7_CN = {
    Text = "In der Nähe des Ausgangspunktes wird man mit einem besonderen Resonanzevent konfrontiert - [Die Nährende Mutter]. Wähle eine Befehlskarte, um ihr das spezielle [Geburt]-Gebet zu verleihen, aber du erhältst auch 3 zufällige Symptomkarten. \n [Geburt]-Gebet: Die Karte erhält Behalten; wenn sie am Ende des Zuges auf der Hand ist, erhält man eine zusätzliche Basiskopie mit Behalten und Verbrauch."
  },
  LanguageConfig_Resonance_Group_Desc_8_CN = {
    Text = "Erforscht man die Nähe des Startpunkts, trifft man auf ein spezielles Resonanzereignis——die [Einschulungsfeier], das [Polares Dämmerungslicht] in das Kartendeck integriert.\n[Polares Dämmerungslicht]: Wähle 1 Befehlskarte aus dem Ziehstapel oder aus dem Ablagestapel und füge sie deiner Hand hinzu, während ihr Arithmetica-Verbrauch auf 0 gesetzt wird. Nach 1 Verwendung verbraucht."
  },
  LanguageConfig_Resonance_Group_Desc_9_CN = {
    Text = "Erforscht man die Nähe des Startpunkts, trifft man auf ein spezielles Resonanzereignis [Einschulung], das [Polares Dämmerungslicht] in das Kartendeck integriert, wobei alle Boni des achten Kapitels erlangt werden."
  },
  LanguageConfig_Resonance_Group_Desc_D05EX_CN = {
    Text = "Erhalte das anfängliche Relikt „Forschungsteam\": Zu Beginn 30 Mitglieder des Forschungsteams. Zu Beginn des Kampfes werden 5 „Verdacht\"-Karten in das Deck gemischt. „Verdacht\": Wenn gespielt, verbraucht man unterschiedliche Anzahlen von Mitgliedern, um verschiedene Effekte auszulösen.\nWährend des Erkundungsprozesses wird man ständig mit dem Dilemma „Verdacht\" konfrontiert, was zu Verlusten unter den Mitgliedern des Forschungsteams führt. Das Erreichen einer Kontaktstelle bietet die Möglichkeit zur Rettung. Bei der letzten sicheren Evakuierung erhält man je nach verbleibenden Mitgliedern des Forschungsteams „Rettungsmedaillen\". Je mehr Mitglieder evakuiert werden, desto mächtiger sind die „Rettungsmedaillen\"."
  },
  LanguageConfig_Resonance_Group_Desc_Horla_CN = {
    Text = "Zu Beginn der Erkundung erhält man das anfängliche Relikt “Orrahs Feder und Tinte“: Nach dem Kampf erhält man 1 Schicht “Tinte“, bei 2 Schichten wird “Tinte“ verbraucht und 1 “Bild“ zufällig ins Deck gelegt.\nIn einem speziellen Resonanzevent [Frühlingsgeschenk] kann man “Dichten opfern“ wählen: Wähle 3 “Imagination“ Karten und lasse Horla “Opfergabe“ für dich schaffen."
  },
  LanguageConfig_Resonance_Group_Desc_Lily_CN = {
    Text = "Im Resonanzereignis „Die Gedanken des Produzenten“ kann die Option „Hilfe von Partnern erbitten“ ein Fortgeschrittenes Gebet 3 aus 1 gewinnen"
  },
  LanguageConfig_Resonance_Group_Desc_MLYM_CN = {
    Text = "Zu Beginn der Erkundung werden 3 Unterstützungskarten zum Deck hinzugefügt: <DerivativeCardKeywords_57:“Eine herzliche Familie“>, <DerivativeCardKeywords_58:“Aufrichtiger Freund“>, <DerivativeCardKeywords_59:“Ein friedliches Leben“>. \n“Eine herzliche Familie“: erhalten Sie 2 Punkte Arithmetica. \n“Aufrichtiger Freund“: füge allen Gegnern 1 Stapel Schwäche und Verwundbarkeit zu. \n“Ein friedliches Leben“: Ziehen Sie 2 Karten."
  },
  LanguageConfig_Resonance_Group_Desc_Railway_CN = {
    Text = "Zu füllen."
  },
  LanguageConfig_Resonance_Group_Desc_SEWD_CN = {
    Text = "“Das Ereignis „Verlangen“ erhält ein zufälliges schuldbehaftetes Relikt oder goldenes Relikt; das Ereignis „Buße“ reinigt das schuldbehaftete Relikt zu einem gesegneten Relikt; das Ereignis „Erlösung“ kann die Symptom-Karte löschen und Belohnungen erhalten.“"
  },
  LanguageConfig_Resonance_Group_Desc_Wangda_CN = {
    Text = "Im Resonanzereignis „Zugriff auf geheime Befehle“ kann die Option „Finanzierung erhalten“ 25 schwarze Siegel und ein zufälliges silbernes Relikt erlangen"
  },
  LanguageConfig_Resonance_Group_Desc_x1_CN = {
    Text = "Beim Resonanzevent “Noch nicht verlorene Bewusstheit“ wird eine Karte “Ersatzgehirnzylinder“ in das Deck gemischt. Der “Ersatzgehirnzylinder“ kann temporär zuvor verwendete Karten speichern und je nach Situation entscheiden, ob sie in die Hand genommen werden sollen."
  },
  LanguageConfig_Resonance_Group_Desc_x2_CN = {
    Text = "Wähle am Ereignis “Die Verwandlung des Lebens“ einen Erwecker aus und verwandle ihn in den “Insektoid“. \n Die Wutregeneration und die Keyflare-Regeneration des “Insektoid“ erhöhen sich um 50 %, alle Befehlskarten haben -1 Arithmetica-Kosten, werden jedoch nach dem Ausspielen verbraucht."
  },
  LanguageConfig_Resonance_Group_Desc_x3_CN = {
    Text = "Bei dem Ereignis “Vorfeier-Ritual“ füge 1 Karte “Spezialmix der Seelenfestnacht“ dem Deck hinzu. \n “Spezialmix der Seelenfestnacht“: Arithmetica-Kosten 1, die kritische Rate und der kritische Schaden aller Erwecker erhöhen sich vorübergehend um 10%. Nachdem du “Spezialmix der Seelenfestnacht“ ausgespielt hast, füge 1 Zutat hinzu, um in diesem Kampf dauerhaft einen spezifischen Effekt zu erhalten!"
  },
