  LanguageConfig_ResurrectionCoinPurchaseTips_CN = {
    Text = "(Nach dem Einlösen wird sofort verbraucht und wiederbelebt. Bei Rückzug wird der Notfall-Gnosis-Körper zurückerstattet. Der Notfall-Gnosis-Körper kann pro Woche maximal 3 Mal gekauft werden, aktuell verbleibende Anzahl: {s1}/3)"
