  LanguageConfig_RootSedimentShopRules_CN = {
    Text = "1. Der Schutzherr kann durch den Verbrauch einer bestimmten Menge an “Ursprünglicher Abscheidung“ Waren eintauschen. \n 2. Wenn das Ermittlungslevel des Schutzherrn steigt, wird der Abscheidungs-Eintauschladen ebenfalls aufgewertet und neue Inhalte freigeschaltet. \n 3. Die Waren im Abscheidungs-Eintauschladen werden in bestimmten Zeitabständen automatisch aktualisiert. \n 4. Der Schutzherr kann durch Erweckung “Ursprüngliche Abscheidung“ erhalten."
