  LanguageConfig_SchoolTowerRuleTxt_CN = {
    Text = "<Title:Lichtloses Reich>\nDas Lichtlose Reich besteht aus einer Reihe von schwierigen Leveln. Erfolgreiches Abschließen der Level ermöglicht den Erhalt reichhaltiger Belohnungen. Zudem kann das Erreichen von kumulierten Sternebewertungen zusätzliche Belohnungen einbringen.\n\n<Title:Forschungsanforderungen>\nDie Level im Lichtlosen Reich erfordern bestimmte Reiche und eine bestimmte Anzahl von Erweckern für die Forschung. Keeper können Details überprüfen und Teams in den Level-Details und in der Teameinrichtungsoberfläche konfigurieren.\n\n<Title:Anfangsrelikt>\nIn den Leveln des Lichtlosen Reiches existieren einzigartige Relikte, die nur in diesem Level Wirkung zeigen. Eine sinnvolle Nutzung der Relikteffekte kann die Forschung erheblich erleichtern."
  },
  LanguageConfig_SchoolTowerTeamBuildFobiddenTips_CN = {
    Text = "Auswahl erfüllt nicht die Teamanforderungen"
  },
  LanguageConfig_School_Activate_CN = {Text = "Aktiviert"},
  LanguageConfig_School_Blood_Content_String_CN = {
    Text = "Zu Rundenbeginn <CardKeyWord:Embryofusion> +20 (steigt mit Lebensverlust, maximal 40). Wenn das Limit erreicht ist, wird 1 <CardKeyWord:\"Embryo\"> in die Hand aufgenommen.\nDie „Verherrlichung„ im Fleisch-Reich verbraucht <CardKeyWord:\"Embryo\"> und löst den <CardKeyWord:Verschlingen>-Effekt aus. Nach der ersten Verschlingung pro Runde erhält man ein Rollen-Schild gleich 2% der Max LP und Temporäre STR gleich 1% der Max LP. (steigt mit Lebensverlust, maximal 2-fach)"
  },
  LanguageConfig_School_Blood_Title_String_CN = {
    Text = "Blutrotes Opfer"
  },
  LanguageConfig_School_Chaos_Content_String_CN = {
    Text = "·Chaosbereich-Erwecker können die Reichsgrenzen überwinden und mit Erweckern anderer Bereiche in einer Formation spielen. \n·Wenn im Team ein Chaos-Erwecker vorhanden ist, erhält man zusätzlich 100% Todwiderstand. \n·Am Ende der Runde und nach der Freisetzung von “Verherrlichung“, <CardKeyWord:Keyflare> +50."
  },
  LanguageConfig_School_Chaos_Title_String_CN = {
    Text = "Universum und seine Phänomene"
  },
  LanguageConfig_School_Dimension_Content_String_CN = {
    Text = "·Die vorübergehende Kopie der ersten Befehlskarte, die in jeder Runde gespielt wird, gelangt in den <CardKeyWord:Hyperraum> und löst deren Sprungeffekt aus. \n·Wenn der Hyperraum sein Limit erreicht, erhältst du eine zusätzliche Hyperdimensionale Runde, in der keine Karten mehr gezogen werden, sondern die Karten aus dem Hyperraum in die Hand aufgenommen werden. In der Hyperdimensionale Runde können alle Sprungeffekte ausgelöst werden."
  },
  LanguageConfig_School_Dimension_Title_String_CN = {
    Text = "Dimensionaler Sprung"
  },
  LanguageConfig_School_Ocean_Content_String_CN = {
    Text = "·Zu Beginn des Kampfes 1 Tentakel erzeugen, das am Rundenende den vorderen Feind angreift.\n·Bei jeder Auslösung von 1 Verherrlichung am Rundenende 1 Tentakel angreifen lassen.\n·Für jede 3 Punkte Stärke 1 Punkt Tentakelschaden gewähren, bei jedem Rückgang von 3 Punkten Stärke verringert sich der Tentakelschaden um 1 Punkt."
  },
