    Text = "Todesverachtung."
  },
  LanguageConfig_StorylineGuide_10_CN = {
    Text = "Natürlich ist Chaos das Ende von allem. Aber es gibt immer welche, die nicht aufgeben wollen zu kämpfen, oder?"
  },
  LanguageConfig_StorylineGuide_11_CN = {
    Text = "Nicht direkt den Himmel über dir ansehen. Nicht direkt in den Abgrund deines Herzens schauen."
  },
  LanguageConfig_StorylineGuide_12_CN = {
    Text = "Essen ist die einzige Tugend in dieser Welt."
  },
  LanguageConfig_StorylineGuide_13_CN = {
    Text = "In der unendlichen Traumwelt gibt es keine Antworten. Es ist an der Zeit, aus diesem Traum zu erwachen."
  },
  LanguageConfig_StorylineGuide_14_CN = {
    Text = "Auf der Bühne des Schicksals haben wir die Rollen, die wir spielen werden, nie wählen können."
  },
  LanguageConfig_StorylineGuide_15_CN = {
    Text = "O Reisende, schreitet behutsam in diese verschneite Nacht. Auf dem Gipfel der entleerten Willen möget ihr das Ende eines großen Traums bezeugen."
  },
  LanguageConfig_StorylineGuide_16_CN = {
    Text = "Temporärer Text"
  },
  LanguageConfig_StorylineGuide_17_CN = {
    Text = "Temporärer Text"
  },
  LanguageConfig_StorylineGuide_18_CN = {
    Text = "Temporärer Text"
  },
  LanguageConfig_StorylineGuide_19_CN = {
    Text = "Temporärer Text"
  },
  LanguageConfig_StorylineGuide_1_CN = {
    Text = "Tritt in den gefährlichen Nebel der Nacht von Lentiniën ein, Schutzherr. Dein Weg beginnt hier."
  },
  LanguageConfig_StorylineGuide_20_CN = {
    Text = "Temporärer Text"
  },
  LanguageConfig_StorylineGuide_2_CN = {
    Text = "Künstler, Verrückter, Asket, Tor... Diese Stadt gehört dir, das Wachsfigurenkabinett, die Wachsfiguren stehen am Anfang der Geschichte und sehnen sich nach deinem Besuch."
  },
  LanguageConfig_StorylineGuide_3_CN = {
    Text = "Der Schnee und der Wind von Rai verabscheuen das Töten, sie wartet auf dich, nur für einen Handel. Sie wird dir das Geheimnis bringen, nach dem du dich sehnst. Ihr Preis ist immer grausam, immer gerecht."
  },
  LanguageConfig_StorylineGuide_4_CN = {
    Text = "Erinnere dich, kämpfe für die Erinnerungen, sterbe für die Erinnerungen. Erinnerungen sind unser Evangelium, unser Grabstein. Außer den Erinnerungen haben wir nichts."
  },
  LanguageConfig_StorylineGuide_5_CN = {
    Text = "Bevor die Sterne fallen, beten wir zum Ozean: Möge das sanfte Rauschen der Wellen uns in den Traum tragen, möge wir in die Arme unserer Heimat zurückkehren und im langen Traum verweilen."
  },
  LanguageConfig_StorylineGuide_6_CN = {
    Text = "Singe — der alte König hat seinen Thron wieder gesehen. Das göttliche Orakel wird jedem frommen Untertanen das Reich Gottes bringen."
  },
  LanguageConfig_StorylineGuide_7_CN = {
    Text = "Höre, bete, rufe, fortpflanze, gehorche den edelsten Idealen und den niedrigsten Begierden. Im Namen der Mutter kann er in Chaos und Angst bestehen."
  },
  LanguageConfig_StorylineGuide_8_CN = {
    Text = "Die ewige Lampe brennt, und das dunkle Licht wird dir den Weg zum Ziel erhellen."
  },
  LanguageConfig_StorylineGuide_9_CN = {
    Text = "Sag ihm, deine Antwort."
  },
  LanguageConfig_StrongerTitle_CN = {
    Text = "Sammle Materialien über das “Übungsinterludium“ und stärke deinen Erweckten!"
  },
  LanguageConfig_StrongerWayTitle_CN = {
    Text = "Wie kann ich stärker werden?"
  },
  LanguageConfig_StrongerWay_CN = {
    Text = "·“Ermittlungseinsatz“ 1-7·Normal freischalten: “Fusionsruine“, um eine große Menge an Erwecker-Entwicklungsmaterialien zu erhalten. \n·“Ermittlungseinsatz“ 3-10·Normal freischalten: “Transzendentes Wesen“, um eine große Menge an Erwecker-Fähigkeits-Upgrade-Materialien zu erhalten. \n·“Ermittlungslevel“ 15 freischalten: “Zweites Schicksalsrad“, um das zweite Schicksalsrad auszurüsten und starke Kampfkraft zu erhalten. \n·“Ermittlungslevel“ 35 freischalten: “Verbotene Aufzeichnung“, um eine große Menge an Bündnissen zu erhalten und die Fähigkeiten des Erweckers zu stärken."
