  LanguageConfig_TrinketAutoRefineStopByMaxTimeLimit_CN = {
    Text = "100 Transkriptionen abgeschlossen."
  },
  LanguageConfig_TrinketAutoRefine_CN = {
    Text = "<Title:Auto-Transkription>\nDie Auto-Transkription kann Transkriptionen schnell und in großen Mengen durchführen.\nWährend der Auto-Transkription wird diese gestoppt, wenn ein Transkriptionsergebnis 1 freigeschaltetes Attribut mit Intensität 8 enthält.\nDie Auto-Transkription kann bis zu 100 Mal durchgeführt werden.\nWenn die Materialien nicht ausreichen, wird die Transkription automatisch gestoppt.\n<Title:Überspringen>\nWährend der Auto-Transkription wird jedes Transkriptionsergebnis angezeigt, und du kannst den Transkriptionsprozess überspringen. Nach dem Überspringen wird das Endergebnis der Auto-Transkription direkt angezeigt."
  },
  LanguageConfig_TrinketAutoSelectTips_CN = {
    Text = "Auto-Auswahl: Priorisiert Bündnisse niedrigerer Qualität und niedrigerer Stufe als Materialien"
  },
  LanguageConfig_TrinketBatchUnbindComingSoon_CN = {
    Text = "Funktion \"Alle lösen\" demnächst verfügbar"
  },
  LanguageConfig_TrinketBatchUnbindTitle_CN = {
    Text = "Alle lösen"
  },
  LanguageConfig_TrinketBindBonusDesc_CN = {
    Text = "Nach dem Binden wird das Hauptattribut des Bündnisses um zusätzliche {s1} erhöht!"
  },
  LanguageConfig_TrinketBindNoneSelectedTips_CN = {
    Text = "Kein Bündnis zum Binden verfügbar. Bitte wähle mindestens eines aus."
  },
  LanguageConfig_TrinketBindRuleDesc_CN = {
    Text = "<Title:Bündnis-Bindung>\nSchutzherren können nun Bündnisse an Erwecker binden.\nJeder Erwecker hat 6 Bindungsslots (ein Bündnis pro Slot).\nEinmal gebunden, wird das primäre Attribut des Bündnisses um 50 % erhöht.\nGebundene Bündnisse erscheinen nicht in deinem Inventar oder im Alchemie-System.\nWenn ein Erwecker kein Bündnis in einem Lineup- oder Unterstützungsslot ausgerüstet hat, wird sein gebundenes Bündnis automatisch ausgerüstet.\nDas Aufwerten eines gebundenen Bündnisses hebt die Bindung nicht auf; seine verstärkten Attribute werden automatisch aktualisiert.\n\n<Title:Bündnis lösen>\nUm eine Bindung zu ändern oder zu entfernen, verwende die Lösen-Option im Bündnis-Bindungsbildschirm.\nDas Lösen eines einzelnen Slots kostet 10 Bündnisse desselben Typs (jede Slot-Position kann als Kosten verwendet werden)."
  },
